strategy({
  name: "Golden Cross MA50 / MA200",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    fast: param.int(50, { min: 10, max: 100, label: "MA nhanh" }),
    slow: param.int(200, { min: 100, max: 250, label: "MA chậm" }),
    trail: param.pct(0.15, { min: 0.05, max: 0.3, label: "Dừng lỗ trượt" }),
    calm: param.pct(0.67, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  signals: (d, p) => {
    const fast = ta.sma(d.close, p.fast);
    const slow = ta.sma(d.close, p.slow);
    return { entry: fast.crossAbove(slow), exit: fast.crossBelow(slow), score: d.value.rolling(20).mean() };
  },
  filter: (d, p) => {
    // Bỏ các mã biến động mạnh nhất, đứng ngoài khi VNINDEX dưới MA200
    const ok = d.ret.rolling(60).std().rank().lte(p.calm);
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  portfolio: { maxPositions: 10 },
  risk: (p) => ({ trailingStop: p.trail }),
});

