strategy({
  name: "MACD cắt lên kèm khối lượng",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    volMult: param.num(1.5, { min: 1, max: 4, step: 0.1, label: "KL / TB20 tối thiểu" }),
    calm: param.pct(0.4, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  signals: (d, p) => {
    const m = ta.macd(d.close, 12, 26, 9);
    const volSpike = d.volume.gt(d.volume.rolling(20).mean().mul(p.volMult));
    // Vào khi histogram cắt lên 0 có khối lượng, trong xu hướng dài hạn tăng; giữ tới khi đường MACD xuống dưới 0
    // (thoát theo histogram thì lệnh quá ngắn, phí và thuế ăn hết lợi nhuận). Nhiều tín hiệu cùng lúc: ưu tiên mã
    // thanh khoản cao
    return {
      entry: m.hist.crossAbove(0).and(volSpike).and(d.close.gt(ta.sma(d.close, 200))),
      exit: m.macd.lt(0),
      score: d.value.rolling(20).mean(),
    };
  },
  filter: (d, p) => {
    const ok = d.ret.rolling(60).std().rank().lte(p.calm);
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  portfolio: { maxPositions: 8 },
  risk: { stopLoss: 0.08 },
});

