strategy({
  name: "EMA 20 / 50 có lọc ADX",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    fast: param.int(20, { min: 5, max: 50, label: "EMA nhanh" }),
    slow: param.int(50, { min: 20, max: 150, label: "EMA chậm" }),
    minAdx: param.int(20, { min: 10, max: 40, label: "ADX tối thiểu" }),
    calm: param.pct(0.6, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  signals: (d, p) => {
    const fast = ta.ema(d.close, p.fast);
    const slow = ta.ema(d.close, p.slow);
    const dmi = ta.adx(d, 14);
    // Xu hướng tăng đủ mạnh: EMA nhanh trên EMA chậm, ADX trên ngưỡng, phe mua áp đảo (+DI > −DI)
    const trend = fast.gt(slow).and(dmi.adx.gt(p.minAdx)).and(dmi.plusDI.gt(dmi.minusDI));
    return {
      entry: trend.and(trend.shift(1).not()),
      exit: fast.lt(slow),
      score: dmi.adx,
    };
  },
  // Bỏ nhóm biến động mạnh nhất (tín hiệu xu hướng của mã đầu cơ hay gãy)
  filter: (d, p) => {
    const ok = d.ret.rolling(60).std().rank().lte(p.calm);
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  portfolio: { maxPositions: 8 },
  risk: { stopLoss: 0.08 },
});

strategy({
  name: "Ichimoku: giá vượt lên trên mây",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    tenkan: param.int(9, { min: 5, max: 20, label: "Tenkan" }),
    kijun: param.int(26, { min: 15, max: 60, label: "Kijun" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  signals: (d, p) => {
    const ich = ta.ichimoku(d, p.tenkan, p.kijun, p.kijun * 2);
    // Mây của phiên hôm nay là Span A / B tính từ `kijun` phiên trước (mây được vẽ dịch về phía trước)
    const spanA = ich.spanA.shift(p.kijun);
    const spanB = ich.spanB.shift(p.kijun);
    // VNINDEX xuống dưới MA200 thì bán luôn (điều kiện thị trường viết thành panel nhiều mã: d.close.gt(0).and(…))
    const weak = d.close.gt(0).and(d.bench.close.lt(ta.sma(d.bench.close, 200)));
    const below = d.close.lt(spanA.min(spanB));
    return {
      entry: d.close.crossAbove(spanA.max(spanB)).and(ich.tenkan.gt(ich.kijun)),
      exit: p.market ? below.or(weak) : below,
      score: d.close.pct(63),
    };
  },
  filter: (d, p) => (p.market ? d.bench.close.gt(ta.sma(d.bench.close, 200)) : d.tradable),
  portfolio: { maxPositions: 8 },
  risk: { stopLoss: 0.1 },
});

