  name: "RSI hồi phục trong xu hướng tăng",
  universe: universe("VN30"),
  period: { from: "2016-01-01" },
  params: {
    len: param.int(14, { min: 2, max: 30, label: "Chu kỳ RSI" }),
    lower: param.num(30, { min: 10, max: 45, label: "Ngưỡng mua" }),
