strategy({
  name: "Mua điều chỉnh về MA20 trong xu hướng tăng",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    trail: param.pct(0.1, { min: 0.05, max: 0.25, label: "Dừng lỗ trượt" }),
    calm: param.pct(0.6, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  signals: (d) => {
    const ma20 = ta.sma(d.close, 20);
    const ma50 = ta.sma(d.close, 50);
    const ma200 = ta.sma(d.close, 200);
    // Các đường MA xếp tăng dần và MA50 đang đi lên
    const uptrend = ma20.gt(ma50).and(ma50.gt(ma200)).and(ma50.gt(ma50.shift(10)));
    // Trong phiên giá lùi chạm MA20 nhưng đóng cửa vẫn trên MA20
    const bounce = d.low.lte(ma20).and(d.close.gt(ma20));
    return { entry: uptrend.and(bounce), exit: d.close.lt(ma50), score: d.close.pct(63) };
  },
  // Bỏ nhóm biến động mạnh nhất: nhịp chỉnh về MA20 của mã đầu cơ hay thành gãy xu hướng
  filter: (d, p) => {
    const ok = d.ret.rolling(60).std().rank().lte(p.calm);
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
