strategy({
  name: "Xoay vòng theo ngành dẫn dắt",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  rebalance: "month",
  params: {
    lookback: param.int(126, { min: 20, max: 250, label: "Số phiên đo đà tăng" }),
    sectors: param.int(3, { min: 1, max: 6, label: "Số ngành mạnh nhất" }),
    top: param.int(10, { min: 3, max: 20, label: "Số mã nắm giữ" }),
    calm: param.pct(0.67, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  rank: (d, p) => {
    const mom = d.close.pct(p.lookback);
    // Gom chỉ số các mã theo ngành
    const groups = new Map();
    d.meta.forEach((m, i) => {
      if (!m.industry) return;
      if (!groups.has(m.industry)) groups.set(m.industry, []);
      groups.get(m.industry).push(i);
    });
    const rows = d.symbols.map(() => new Float32Array(d.days.length).fill(NaN));
    for (let t = 0; t < d.days.length; t++) {
      // Đà tăng trung bình của từng ngành (cần ít nhất 3 mã có dữ liệu)
      const ranked = [];
      for (const members of groups.values()) {
        const vals = members.map((i) => mom.get(i, t)).filter((v) => v === v);
        if (vals.length >= 3) ranked.push({ members, avg: vals.reduce((a, b) => a + b, 0) / vals.length });
      }
      ranked.sort((a, b) => b.avg - a.avg);
      // Chỉ chấm điểm các mã thuộc những ngành mạnh nhất; điểm = đà tăng của chính mã đó
      for (const g of ranked.slice(0, p.sectors)) for (const i of g.members) rows[i][t] = mom.get(i, t);
    }
    return Panel.fromRows(d.symbols, d.days, rows);
  },
  filter: (d, p) => {
    // Bỏ các mã biến động mạnh nhất, đứng ngoài khi VNINDEX dưới MA200
    const ok = d.close.gt(ta.sma(d.close, 50)).and(d.ret.rolling(60).std().rank().lte(p.calm));
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  select: (p) => ({ top: p.top, weight: "equal" }),
});

