strategy({
  name: "Beta thấp xoay vòng hàng quý",
  universe: universe("HOSE").liquid(10e9).top(240),
  period: { from: "2016-01-01" },
  rebalance: "quarter",
  params: {
    window: param.int(250, { min: 60, max: 500, label: "Cửa sổ tính beta" }),
    top: param.int(15, { min: 5, max: 40, label: "Số mã" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  rank: (d, p) => {
    // Beta = cov(lợi nhuận mã, lợi nhuận VNINDEX) / var(lợi nhuận VNINDEX) trên `window` phiên
    const m = d.bench.close.pct(1);
    const r = d.ret;
    const cov = r.mul(m).rolling(p.window).mean().sub(r.rolling(p.window).mean().mul(m.rolling(p.window).mean()));
    return cov.div(m.rolling(p.window).var()).neg();
  },
  // Beta thấp thường là mã đang giảm riêng lẻ: chỉ chọn mã trên MA200, đứng ngoài khi VNINDEX dưới MA200
  filter: (d, p) => {
    const ok = d.close.gt(ta.sma(d.close, 200));
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  select: (p) => ({ top: p.top, weight: "equal" }),
});

