  rank: (d) => growth(d, 0),
  filter: (d, p) => {
    const now = growth(d, 0);
    const before = growth(d, 1);
    const sale = d.fin("NetSale");
    const saleBefore = d.fin("NetSale", { ago: 4 });
    const ok = now
      .gte(p.minGrowth)
      .and(now.gt(before))
      .and(before.gt(0))
      .and(sale.gt(saleBefore))
      .and(d.close.gt(ta.sma(d.close, 200)));
    return p.market ? ok.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : ok;
  },
  select: (p) => ({ top: p.top, weight: "equal" }),
});

