    maxDebt: param.num(1.5, { min: 0.5, max: 5, step: 0.5, label: "Nợ phải trả / vốn chủ tối đa" }),
    top: param.int(10, { min: 5, max: 30, label: "Số mã nắm giữ" }),
    calm: param.pct(0.7, { min: 0.2, max: 1, label: "Nhóm biến động thấp (% rổ)" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  rank: (d) => d.earningsYield,
  // Ngân hàng không có chỉ tiêu nợ phải trả / vốn chủ → không loại
  filter: (d, p) =>
    d.eps.gt(0)
      .and(d.roe.gte(p.minRoe))
      .and(d.debtToEquity.fillna(0).lte(p.maxDebt))
      .and(d.profitGrowth.gt(0))
      .and(d.close.gt(ta.sma(d.close, 100)))
      .and(d.ret.rolling(60).std().rank().lte(p.calm))
      .and(p.market ? d.bench.close.gt(ta.sma(d.bench.close, 200)) : d.tradable),
  select: (p) => ({ top: p.top, weight: "equal", minScore: 0, maxWeight: 1 / p.top }),
});

// Mua khi phá vỡ mẫu hình tăng giá: cốc tay cầm, hai đáy (W), tam giác tăng — vào lệnh ở phiên giá đóng cửa vượt miệng cốc / đỉnh
// giữa / cạnh trên lần đầu với khối lượng từ `minVol` lần TB20 (ta.patterns, ZigZag nhân quả). Lợi thế của mẫu hình tích lũy chậm
// trong 2–3 tháng nên giữ lâu (mặc định tối đa 120 phiên) và cắt lỗ rộng; giữ 60 phiên, cắt lỗ 8% thì gần như mất lợi thế.
// Kết quả nhạy với cách thoát lệnh và phụ thuộc nhiều vào năm 2021 — xem "bỏ năm tốt nhất" trước khi dùng.
strategy({
  name: "Mua khi phá vỡ mẫu hình tăng giá",
  universe: universe("ALL").liquid(3e9).top(240),
  period: { from: "2016-01-01" },
  params: {
    cup: param.bool(true, { label: "Cốc tay cầm" }),
    w: param.bool(true, { label: "Hai đáy (W)" }),
    tri: param.bool(true, { label: "Tam giác tăng" }),
    minVol: param.num(1.5, { min: 1, max: 3, step: 0.1, label: "KL phiên phá vỡ / TB20 từ" }),
    th: param.pct(0.08, { min: 0.05, max: 0.12, label: "Ngưỡng đỉnh / đáy (ZigZag)" }),
    hold: param.int(120, { min: 20, max: 250, label: "Giữ tối đa (phiên)" }),
    stop: param.pct(0.12, { min: 0.05, max: 0.25, label: "Cắt lỗ" }),
    market: param.bool(true, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  portfolio: { maxPositions: 10, sizing: "equal" },
  risk: (p) => ({ stopLoss: p.stop, maxHoldDays: p.hold }),
  signals: (d, p) => {
    const only = [p.cup && "cup", p.w && "doubleBottom", p.tri && "ascTriangle"].filter(Boolean);
    if (!only.length) throw new Error("Chọn ít nhất một mẫu hình");
    const pt = ta.patterns(d, { only, th: p.th, minVol: p.minVol });
    let entry = pt.breakout.gt(0);
    if (p.market) entry = entry.and(d.bench.close.gt(ta.sma(d.bench.close, 200)));
    // Nhiều tín hiệu cùng phiên: ưu tiên phiên phá vỡ khối lượng lớn
    return { entry, score: pt.volRatio };
  },
});

// Rổ cổ phiếu lớn theo lạm phát (tên cũ "Rổ cổ phiếu lớn theo đèn lạm phát"): nắm đều 30 mã thanh khoản lớn nhất HOSE (theo thời
// điểm), cân bằng hàng tháng; khi lạm phát (CPI so cùng kỳ) cao hơn `look` phiên trước thì để tiền mặt. Số CPI là số đã công bố
// trước từng phiên nên không nhìn trước. 2016–10/2026: lợi nhuận gần như rổ luôn nắm (khoảng 9,6% so với 9,4%/năm) nhưng sụt giảm
// tối đa còn khoảng −21% thay vì −51%.
strategy({
  name: "Rổ cổ phiếu lớn theo lạm phát",
  universe: universe("HOSE").liquid(20e9).top(30),
  period: { from: "2016-01-01" },
  rebalance: "month",
  params: {
    light: param.bool(true, { label: "Để tiền mặt khi lạm phát tăng" }),
    look: param.int(63, { min: 21, max: 126, label: "So CPI với bao nhiêu phiên trước" }),
    rates: param.bool(false, { label: "Thêm điều kiện lãi suất (LNH qua đêm tăng)" }),
  },
  rank: (d) => d.value.rolling(20).mean(),
  filter: (d, p) => {
    let ok = d.close.gt(0);
    if (p.light) {
      const cpi = d.macro("cpi_yoy");
      ok = ok.and(cpi.gt(cpi.shift(p.look)).not());
    }
    if (p.rates) {
      const ib = d.macro("ib_on");
      ok = ok.and(ib.rolling(20).mean().gt(ib.rolling(120).mean()).not());
    }
    return ok;
  },
  select: { top: 30, weight: "equal", maxWeight: 1 / 30 },
});

// Xoay vòng ngành theo chu kỳ lãi suất: lãi suất liên ngân hàng 3 tháng (TB 20 phiên) thấp hơn `look` phiên trước → nắm nhóm hưởng
// lợi khi tiền rẻ (chứng khoán, bất động sản, bán lẻ); lãi suất tăng → nhóm phòng thủ (điện, nước, dược, thực phẩm, đồ uống) hoặc
// tiền mặt. Trong nhóm chọn `top` mã đà tăng 3 tháng mạnh nhất, trên MA50. Thử nghiệm: chỉ khoảng ba chu kỳ lãi suất từ 2014 và
// kết quả nhạy với cách đo (so với 42 hoặc 126 phiên thay vì 63 thì lợi nhuận giảm mạnh).
const SENSITIVE = /môi giới|bất động sản|Bán lẻ/i;
const DEFENSIVE = /Điện|nước|Dược|thực phẩm|Đồ uống|Bia/i;
strategy({
  name: "Xoay vòng ngành theo chu kỳ lãi suất",
  universe: universe("ALL").liquid(5e9).top(240),
  period: { from: "2016-01-01" },
  rebalance: "month",
  params: {
    top: param.int(8, { min: 3, max: 20, label: "Số mã nắm giữ" }),
    defensive: param.bool(true, { label: "Lãi suất tăng thì nắm nhóm phòng thủ (tắt = tiền mặt)" }),
    look: param.int(63, { min: 21, max: 126, label: "So lãi suất với bao nhiêu phiên trước" }),
    market: param.bool(false, { label: "Chỉ mua khi VNINDEX > MA200" }),
  },
  rank: (d) => d.close.pct(63),
  filter: (d, p) => {
    const nT = d.days.length;
    const group = (re) => Panel.fromRows(d.symbols, d.days, d.meta.map((m) => new Float32Array(nT).fill(re.test(`${m.industry || ""} ${m.sector || ""}`) ? 1 : 0)));
    const ib = d.macro("ib_3m").rolling(20).mean();
    const easing = ib.lt(ib.shift(p.look));
    const sensitive = group(SENSITIVE).gt(0).and(easing);
    const ok = p.defensive ? sensitive.or(group(DEFENSIVE).gt(0).and(easing.not())) : sensitive;
    const trend = ok.and(d.close.gt(ta.sma(d.close, 50)));
    return p.market ? trend.and(d.bench.close.gt(ta.sma(d.bench.close, 200))) : trend;
  },
  select: (p) => ({ top: p.top, weight: "equal", maxWeight: 1 / p.top }),
});

// Cổ phiếu chứng khoán theo chu kỳ lãi suất: chỉ nắm `top` mã chứng khoán đà tăng 3 tháng mạnh nhất khi lãi suất liên ngân hàng 3 tháng
// (TB 20 phiên) thấp hơn 3 tháng trước — tiền rẻ thì thanh khoản và lợi nhuận môi giới, tự doanh tăng; còn lại để tiền mặt.
// 2016–10/2026 khoảng 14,5%/năm so với 2,6% nếu luôn nắm nhóm này, năm 2022 giảm khoảng 20% thay vì 67%. Thử nghiệm: dùng lãi suất
// qua đêm thay cho 3 tháng thì kết quả kém hẳn.
strategy({
  name: "Cổ phiếu chứng khoán theo chu kỳ lãi suất",
  universe: universe("ALL").industry("Dịch vụ môi giới").liquid(3e9).top(30),
  period: { from: "2016-01-01" },
  rebalance: "month",
  params: {
    cycle: param.bool(true, { label: "Chỉ nắm khi lãi suất LNH 3 tháng giảm" }),
    top: param.int(5, { min: 2, max: 15, label: "Số mã nắm giữ" }),
  },
  rank: (d) => d.close.pct(63),
  filter: (d, p) => {
    const ok = d.close.gt(0);
    if (!p.cycle) return ok;
    const ib = d.macro("ib_3m").rolling(20).mean();
    return ok.and(ib.lt(ib.shift(63)));
  },
  select: (p) => ({ top: p.top, weight: "equal", maxWeight: 1 / p.top }),
});
